    private void expire(){stopSession();if(phase.equals("review"))return;++generation;draftId="";busy=false;go("expired","backup-restart");}
    private void pick(){try{Intent intent=new Intent(Build.VERSION.SDK_INT>=19?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_GET_CONTENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);external=true;sheet.dialog.hide();ui.startActivityForResult(intent,PICK);}catch(ActivityNotFoundException|SecurityException unavailable){external=false;sheet.dialog.show();error="系统文件选择器不可用，可浏览存储或通过手机传入";render();}}
    private void source(int value){source=value;folder=boundary=null;tree=current=null;parents.clear();if(source<2&&Build.VERSION.SDK_INT>=21){tree=FileTransferSource.Documents.remembered(ui,source==1);if(tree!=null&&FileTransferSource.Documents.persistedRead(ui,tree))current=FileTransferSource.Documents.root(tree);else tree=null;}go("files","backup-file-up");readFiles();}
    private void readFiles(){if(!open())return;int version=++listVersion;files=Collections.emptyList();busy=true;error="";render();int at=source;File path=folder;Uri root=tree,location=current;worker.execute(()->{List<FileTransferSource.Item> values=new ArrayList<>();String failure="";try{if(at==2){FileTransferStore store=new FileTransferStore(new File(ui.getFilesDir(),"received-files"));for(FileTransferStore.Entry entry:store.list())if(backupName(entry.name))values.add(new FileTransferSource.Item(entry.name,entry.bytes,false,Uri.fromFile(store.file(entry.id)),store.file(entry.id)));}else for(FileTransferSource.Item item:root!=null?FileTransferSource.Documents.children(ui,root,location):path==null?FileTransferSource.volumes(ui,at==1):FileTransferSource.children(path))if(item.directory||backupName(item.name))values.add(item);}catch(IOException|RuntimeException unavailable){failure="目录无法读取，请检查授权或存储连接";}String problem=failure;main.post(()->{if(!open()||version!=listVersion||!phase.equals("files"))return;busy=false;files=values;error=problem;render();});});}
    private static boolean backupName(String name){String value=name.toLowerCase(Locale.ROOT);return value.endsWith(".json")||value.endsWith(".zip");}
    private void files(){LinearLayout options=ui.row();Button up=button("上一级","backup-file-up",()->{if(tree!=null){if(parents.isEmpty()){tree=current=null;}else current=parents.pop();}else if(folder!=null){folder=folder.equals(boundary)?null:folder.getParentFile();}else{go("import","backup-local-import");return;}readFiles();},false);options.addView(up,new LinearLayout.LayoutParams(-2,p(46.08f)));if(source<2){Button choose=button("读取选项","backup-file-options",this::fileOptions,false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,p(46.08f));lp.leftMargin=p(8);options.addView(choose,lp);}sheet.body.addView(options);copy(source==2?"已接收文件":tree!=null?"已授权目录":folder==null?"存储根目录":folder.getName(),16,25.6f,12,8,UiPalette.SECONDARY);LinearLayout rows=ui.listGroup();sheet.body.addView(rows);if(files.isEmpty()&&!busy)note("没有可读取的备份，可使用系统选择文件、授权目录或手机传入。");for(FileTransferSource.Item item:files)row(rows,item.name,item.directory?"文件夹":FileTransferSource.size(item.bytes),"backup-file-"+item.uri,()->{if(item.directory){if(tree!=null){parents.push(current);current=item.uri;}else{if(folder==null)boundary=item.file;folder=item.file;}focus="backup-file-up";readFiles();}else importFile(item);});}
    private void fileOptions(){go("file-options","backup-file-pick");}
    private void fileOptionsBody(){sheet.heading.setText("读取桌面备份");LinearLayout options=group("读取选项");row(options,"系统选择文件","单个备份","backup-file-pick",this::pick);if(Build.VERSION.SDK_INT>=21)row(options,"授权目录","选择本机或 U 盘目录","backup-file-tree",()->{try{external=true;sheet.dialog.hide();ui.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),TREE);}catch(ActivityNotFoundException|SecurityException unavailable){external=false;sheet.dialog.show();error="系统目录授权不可用";go("files","backup-file-options");}});row(options,"重新读取存储","刷新","backup-file-reread",()->{phase="files";if(Build.VERSION.SDK_INT>=23&&Build.VERSION.SDK_INT<33&&ui.checkSelfPermission(android.Manifest.permission.READ_EXTERNAL_STORAGE)!=android.content.pm.PackageManager.PERMISSION_GRANTED){ui.requestPermissions(new String[]{android.Manifest.permission.READ_EXTERNAL_STORAGE},PERMISSION);}else readFiles();});restoreFocus();}
    private void importFile(FileTransferSource.Item item){if(busy)return;if(!backupName(item.name)){error="请选择 JSON 或 ZIP 桌面备份";render();return;}int version=++generation;busy=true;error=message="";render();worker.execute(()->{try(InputStream input=item.file!=null?new FileInputStream(item.file):ui.getContentResolver().openInputStream(item.uri)){if(input==null)throw new IOException("文件无法读取");String id=manager.receive(input,item.bytes,()->!destroyed&&version==generation);main.post(()->{if(open()&&version==generation){busy=false;draftId=id;loadDraft(id);}});}catch(IOException|RuntimeException unavailable){String problem=unavailable.getMessage();main.post(()->{if(open()&&version==generation){busy=false;error=problem==null?"备份未导入，请检查文件和授权":problem;render();}});}});}
    void activityResult(int request,int result,Intent data){
        if(request!=PICK&&request!=TREE&&request!=SAVE||!open())return;external=false;sheet.dialog.show();if(result!=android.app.Activity.RESULT_OK||data==null||data.getData()==null){message="已取消，当前桌面保持不变";render();return;}Uri uri=data.getData();if(request==SAVE){File file=exported;if(file==null||!file.isFile()){error="导出文件已不可用，请重新导出";render();return;}busy=true;render();int version=++generation;worker.execute(()->{String problem="";try(InputStream input=new FileInputStream(file);OutputStream output=ui.getContentResolver().openOutputStream(uri,"w")){if(output==null)throw new IOException("保存位置不可写");byte[] buffer=new byte[64*1024];int count;while((count=input.read(buffer))!=-1){DesktopBackupRecord.require(!destroyed&&version==generation,"保存已中断");output.write(buffer,0,count);}output.flush();}catch(IOException|RuntimeException failure){problem="备份文件未完整保存，请检查保存位置后重试";}String failure=problem;main.post(()->{if(open()&&version==generation){busy=false;error=failure;message=failure.isEmpty()?"备份文件已保存":"";render();}});});}else if(request==TREE){if(!FileTransferSource.Documents.validTree(uri)){error="目录授权无效，请重新选择";render();return;}tree=uri;current=FileTransferSource.Documents.root(uri);folder=boundary=null;parents.clear();try{FileTransferSource.Documents.remember(ui,source==1,uri,data.getFlags());}catch(IOException unavailable){message=unavailable.getMessage();}phase="files";focus="backup-file-up";readFiles();}else{int version=++generation;worker.execute(()->{try{FileTransferSource.Item item=FileTransferSource.selected(ui,uri);main.post(()->{if(open()&&version==generation)importFile(item);});}catch(IOException|RuntimeException failure){main.post(()->{if(open()&&version==generation){error="所选文件无法读取，请检查授权后重试";render();}});}});}
    }
    void permissionResult(int request){if(request==PERMISSION&&open()){phase="files";readFiles();}}
    private void back(){
        if(busy)return;if(parentSheet!=null){if(phase.equals("actions")){sheet.dialog.dismiss();return;}if(phase.equals("delete")||phase.equals("record")||phase.equals("formats")){go("actions",(phase.equals("delete")?"backup-delete-":phase.equals("record")?"backup-restore-":"backup-export-")+recordId);return;}}if(phase.equals("delete")){chosen=null;go("list","backup-record-"+recordId);read();return;}if(phase.equals("review"))stopSession();if(phase.equals("list")){close();return;}if(phase.equals("session")||phase.equals("expired")){stopSession();go(importSession?"import":"formats",importSession?"backup-phone-import":"backup-export-phone");}else if(phase.equals("files")||phase.equals("file-options")){go("import","backup-local-import");}else if(phase.equals("formats")&&!exportCurrent){chosen=null;go("list","backup-record-"+recordId);read();}else{chosen=null;draftId="";go("list",recordId.isEmpty()?"backup-import":"backup-record-"+recordId);read();}}
    void resume(){active=true;if(!open()||external)return;sheet.dialog.show();if(phase.equals("list"))read();else if(phase.equals("files"))readFiles();else if(phase.equals("file-options"))fileOptions();else render();}
    void pause(){active=false;if(server!=null||starting){expire();}else if(phase.equals("session")||phase.equals("receiving")){stopSession();busy=false;phase="expired";focus="backup-restart";}else if(!external&&phase.equals("formats")&&busy){++generation;busy=false;exported=null;error="导出已停止，请重新选择保存位置";}}
    void save(Bundle state){if(!open())return;Bundle value=new Bundle();String scene=phase.equals("session")||phase.equals("receiving")?"expired":phase;value.putString("phase",scene);value.putString("focus",scene.equals("expired")?"backup-restart":focus);value.putString("error",error);value.putString("message",message);value.putString("record",recordId);value.putString("draft",draftId);value.putString("held",heldId);value.putBoolean("media",media);value.putBoolean("current",exportCurrent);value.putBoolean("importing",importSession);value.putBoolean("external",external);value.putBoolean("record-dialog",parentSheet!=null);value.putInt("source",source);if(exported!=null)value.putString("export",exported.getName());if(folder!=null)value.putString("folder",folder.getAbsolutePath());if(boundary!=null)value.putString("boundary",boundary.getAbsolutePath());if(tree!=null){value.putString("tree",tree.toString());value.putString("location",current.toString());ArrayList<String> links=new ArrayList<>();for(Uri parent:parents)links.add(parent.toString());value.putStringArrayList("parents",links);}state.putBundle("desktop-backup",value);}
    void restore(Bundle state){Bundle value=state==null?null:state.getBundle("desktop-backup");if(value==null)return;phase=value.getString("phase","list");focus=value.getString("focus","backup-save");error=value.getString("error","");message=value.getString("message","");recordId=value.getString("record","");draftId=value.getString("draft","");heldId=value.getString("held","");media=value.getBoolean("media");exportCurrent=value.getBoolean("current",true);importSession=value.getBoolean("importing");external=value.getBoolean("external");source=value.getInt("source");String name=value.getString("export");if(name!=null&&name.matches("[a-f0-9-]{36}\\.(json|zip)"))exported=new File(new File(ui.getCacheDir(),"desktop-backup-export"),name);if(value.containsKey("folder"))folder=new File(value.getString("folder"));if(value.containsKey("boundary"))boundary=new File(value.getString("boundary"));if(value.containsKey("tree")){tree=Uri.parse(value.getString("tree"));current=Uri.parse(value.getString("location"));ArrayList<String> links=value.getStringArrayList("parents");if(links!=null)for(String link:links)parents.addLast(Uri.parse(link));}boolean modal=value.getBoolean("record-dialog",phase.equals("record")||phase.equals("delete"));String scene=phase,target=focus,problem=error,result=message;
        if(modal){phase="list";focus="backup-record-"+recordId;error=message="";}create();if(modal){phase=scene;focus=target;error=problem;message=result;recordDialog();}
        ManagementUi.Sheet restored=sheet;if(phase.equals("review")&&!draftId.isEmpty())loadDraft(draftId);else if((phase.equals("actions")||phase.equals("record")||phase.equals("delete"))&&!recordId.isEmpty())manager.read(store->store.find(recordId),(entry,failure)->{if(open()&&sheet==restored){chosen=entry;if(!failure.isEmpty()){phase="list";error=failure;if(parentSheet!=null)sheet.dialog.dismiss();read();}render();}});else if((phase.equals("formats")||phase.equals("expired"))&&!heldId.isEmpty())manager.held(heldId,(entry,failure)->{if(open()&&sheet==restored){chosen=entry;if(!failure.isEmpty()){phase="list";error=failure;if(parentSheet!=null)sheet.dialog.dismiss();read();}render();}});else if(phase.equals("list"))read();}
    void close(){if(!busy&&sheet!=null)sheet.dialog.dismiss();}
    void destroy(){destroyed=true;++generation;++listVersion;manager.unlisten(changed);stopSession();if(sheet!=null){sheet.dialog.setOnDismissListener(null);sheet.dialog.dismiss();sheet=null;}if(parentSheet!=null){parentSheet.dialog.setOnDismissListener(null);parentSheet.dialog.dismiss();parentSheet=null;}ui.unregisterReceiver(screen);main.removeCallbacksAndMessages(null);worker.shutdown();}
